 function mergeIncoming(incoming){const byKey=new Map(state.records.map(r=>[r.key,r]));for(const n of incoming){const old=byKey.get(n.key);if(!old){byKey.set(n.key,n);continue;}old.sources.push(...n.sources);old.issues.push(...n.issues);const seen=new Set(old.rows.map(x=>x.map(display).join('|')));for(const row of n.rows){const sig=row.map(display).join('|');if(!seen.has(sig)){old.rows.push(row);seen.add(sig);}}for(const name of n.names)if(!old.names.includes(name))old.names.push(name);for(const j of n.judicial)old.judicial.push(j);for(const field of ['coord','gdo','body','team','title','crime','province','district','date','impunity'])if(!old[field]&&n[field])old[field]=n[field];if(!old.group&&n.group)old.group=n.group;old.search=norm([old.search,n.search,old.team].join(' '));}state.records=[...byKey.values()];}
